/** @brief NV3031A：设置并应用背光 PWM。 */
int BSP_LCD_BL_SetPct(uint8_t brightness_pct)
{
    if (brightness_pct > LCD_BL_MAX_BRIGHTNESS_PCT)
    {
        brightness_pct = LCD_BL_MAX_BRIGHTNESS_PCT;
    }

    s_bl_saved = brightness_pct;
